CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE document_chunks (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    document_id BIGINT NOT NULL,
    chunk_index INTEGER NOT NULL,
    content TEXT NOT NULL,
    page_start INTEGER,
    page_end INTEGER,
    -- No fixed typmod until M6-T01B selects a provider/model. Validate each row instead.
    embedding vector NOT NULL,
    embedding_model VARCHAR(255) NOT NULL,
    embedding_dimensions INTEGER NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_document_chunks_document
        FOREIGN KEY (document_id) REFERENCES documents(id) ON DELETE CASCADE,
    CONSTRAINT uq_document_chunks_document_index UNIQUE (document_id, chunk_index),
    CONSTRAINT chk_document_chunks_index CHECK (chunk_index >= 0),
    CONSTRAINT chk_document_chunks_content CHECK (length(trim(content)) > 0),
    CONSTRAINT chk_document_chunks_model CHECK (length(trim(embedding_model)) > 0),
    CONSTRAINT chk_document_chunks_dimensions CHECK (
        embedding_dimensions > 0 AND vector_dims(embedding) = embedding_dimensions
    ),
    CONSTRAINT chk_document_chunks_pages CHECK (
        (page_start IS NULL AND page_end IS NULL)
        OR (page_start IS NOT NULL AND page_end IS NOT NULL
            AND page_start >= 1 AND page_end >= page_start)
    )
);

-- The unique index above also supports document-scoped reads and cascading deletes.
-- Course/ownership is resolved through documents -> courses -> workspaces.
-- Add a model/dimension-specific ANN index after the embedding contract is selected.
